window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0891077d2a366bc1"]={"versions": [{"id": "FIG-0891077d2a366bc1", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Strukturdiagramm (AUTOSAR Template Specification).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der hierarchischen Dokumentationsstruktur im AUTOSAR-Metamodell (<em>Generic Structure Template</em> – <code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>, Kapitel 9: Documentation).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die formale ARXML-Repräsentation von Dokumentationsinhalten (<code>Chapter</code>, <code>Topic1</code>, Fließtextinhalte). Dies ermöglicht das strukturierte Einbetten, Splitten und Variieren technischer Spezifikationen, Architekturdokumente und generierter Berichte direkt innerhalb des AUTOSAR-Datenmodells.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Chapter</code>:</strong> \n<ul class=\"fig-list\"><li>Repräsentiert ein eigenständiges Dokumentenkapitel.\n</li><li>Realisiert die Metamodell-Traits <code>Identifiable</code> (Besitz eines <code>shortName</code>, Namespace- und Adressierungsfähigkeit) sowie <code>Paginateable</code> (Paginierungssteuerung, z. B. erzwungene Seitenumbrüche).\n</li></ul>\n</li><li><strong><code>ChapterModel</code>:</strong>\n<ul class=\"fig-list\"><li>Zentraler Inhaltscontainer eines Kapitels.\n</li><li>Steht in einer strikten 1:1-Kompositionsbeziehung zu <code>Chapter</code> (<code>+chapterModel 1</code> als Ziel, Kompositionsraute bei <code>Chapter</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterContent</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapterContent</code>, Kardinalität <code>0..1</code>).\n</li><li>Nimmt primäre Dokumentationsstrukturen auf (z. B. Absätze, Listen, Tabellen, Abbildungen). Der Stereotyp <code>«atpMixed»</code> gestattet XML-Mixed-Content (Kombination aus Rohtext und XML-Elementtags).\n</li></ul>\n</li><li><strong><code>«atpMixed» TopicOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+topic1</code>, Kardinalität <code>0..1</code>).\n</li><li>Vermittlungsknoten zur Kapselung von Unterthemen oder dynamischen MSR-Modellabfragen (<em>MsrQuery</em>).\n</li><li>Komponiert <code>Topic1</code> (<code>+topic1</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong><code>Topic1</code>:</strong>\n<ul class=\"fig-list\"><li>Repräsentiert eine thematische Untereinheit (<code>Identifiable</code>, <code>Paginateable</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapter</code>, Kardinalität <code>0..1</code>).\n</li><li>Ermöglicht die rekursive Schachtelung von Unterkapiteln oder die Einbindung über dynamische Modellabfragen.\n</li><li>Komponiert rekursiv <code>Chapter</code> (<code>+chapter</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong>Stereotypen und Tagged Values:</strong>\n<ul class=\"fig-list\"><li><strong><code>«atpSplitable»</code></strong> (auf den Kompositionen zu <code>Topic1</code> und <code>Chapter</code>): Erlaubt das Splitten des Modells über mehrere ARXML-Dateien hinweg. Einzelne Kapitel oder Topics können physisch disloziert vorliegen und zur Verarbeitungszeit zusammengeführt werden.\n</li><li><strong><code>«atpVariation»</code></strong> (auf den Kompositionen zu <code>Topic1</code> und <code>Chapter</code>): Markiert Variation Points für das AUTOSAR-Variantenmanagement.\n</li><li><strong>Tagged Value <code>vh.latestBindingTime = postBuild</code>:</strong> Festlegung, dass Dokumentationsvarianten bis zum Post-Build-Zeitpunkt über Systemkonstanten/Variantenkriterien gebunden bzw. selektiert werden können.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeitverhalten im Sinne von Mikrocontroller-Ausführung, BSW-Zustandswechseln, RTOS-Tasks oder API-Callbacks.\n</li><li><strong>Tool- und Build-Pipeline-Ablauf:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen &amp; Splitting-Auflösung (<code>«atpSplitable»</code>):</strong> Der ARXML-Parser konsolidiert verteilt abgelegte Kapitel und Topics über deren <code>Identifiable</code>-Identifikatoren zu einem kohärenten AST.\n</li><li><strong>Query-Evaluation:</strong> <code>TopicOrMsrQuery</code> und <code>ChapterOrMsrQuery</code> werden zur Tool-Laufzeit ausgewertet; dynamische Abfragen werden aufgelöst und durch konkrete Modellelemente substituiert.\n</li><li><strong>Variabilitätsauflösung (<code>«atpVariation»</code>):</strong> Evaluierung von Bindungsformeln bis hin zu <code>postBuild</code>. Nicht aktive Zwecke/Topics werden anhand des gewählten Konfigurationssatzes aus dem Ausgabe-Dokumentenbaum eliminiert.\n</li><li><strong>Dokumenten-Rendering:</strong> Generatoren transformieren die aggregierte Baumstruktur unter Berücksichtigung der <code>Paginateable</code>-Attribute in Render-Formate (PDF, HTML, DITA).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- und Stack-Entwickler:</strong> Keine direkte Auswirkung auf Embedded-C-Schnittstellen (<code>Std_Types.h</code>, MCAL, BSW-APIs); rein deskriptives Metamodell für Dokumentations- und Spezifikationsdaten.\n</li><li><strong>Toolchain-, Generator- und Validierungs-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Mixed-Content-Verarbeitung:</strong> Schema-Parser müssen den Stereotyp <code>«atpMixed»</code> für XML-Text-Markup (Whitespace, Inline-Tags) deterministisch verarbeiten.\n</li><li><strong>Rekursionstiefe:</strong> Dokumenten-Parser müssen die zyklische Referenzstruktur <code>Chapter -&gt; ChapterModel -&gt; ChapterOrMsrQuery -&gt; Chapter</code> zirkulationsfrei traversieren können.\n</li><li><strong>Multi-File-Handling:</strong> Splitting (<code>«atpSplitable»</code>) erfordert ein verzögertes Linken von Referenzen (<code>+topic1</code>, <code>+chapter</code>), da Zielknoten in separaten ARXML-Artefakten gepflegt werden können.\n</li><li><strong>Variantenauflösung:</strong> Bei der automatisierten Generierung von Release-Dokumentationen (z. B. Safety Manuals, SWS) muss die Toolchain die Post-Build-Variantenkriterien korrekt auf den Dokumentbaum anwenden, um versions- und kundenreine Dokumente auszugeben.\n</li></ul>\n</li></ul>"}, {"id": "FIG-881bffb71b63a4fd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Strukturdiagramm (AUTOSAR Template Specification).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der hierarchischen Dokumentationsstruktur im AUTOSAR-Metamodell (<em>Generic Structure Template</em> – <code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>, Kapitel 9: Documentation).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die formale ARXML-Repräsentation von Dokumentationsinhalten (<code>Chapter</code>, <code>Topic1</code>, Fließtextinhalte). Dies ermöglicht das strukturierte Einbetten, Splitten und Variieren technischer Spezifikationen, Architekturdokumente und generierter Berichte direkt innerhalb des AUTOSAR-Datenmodells.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Chapter</code>:</strong> \n<ul class=\"fig-list\"><li>Repräsentiert ein eigenständiges Dokumentenkapitel.\n</li><li>Realisiert die Metamodell-Traits <code>Identifiable</code> (Besitz eines <code>shortName</code>, Namespace- und Adressierungsfähigkeit) sowie <code>Paginateable</code> (Paginierungssteuerung, z. B. erzwungene Seitenumbrüche).\n</li></ul>\n</li><li><strong><code>ChapterModel</code>:</strong>\n<ul class=\"fig-list\"><li>Zentraler Inhaltscontainer eines Kapitels.\n</li><li>Steht in einer strikten 1:1-Kompositionsbeziehung zu <code>Chapter</code> (<code>+chapterModel 1</code> als Ziel, Kompositionsraute bei <code>Chapter</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterContent</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapterContent</code>, Kardinalität <code>0..1</code>).\n</li><li>Nimmt primäre Dokumentationsstrukturen auf (z. B. Absätze, Listen, Tabellen, Abbildungen). Der Stereotyp <code>«atpMixed»</code> gestattet XML-Mixed-Content (Kombination aus Rohtext und XML-Elementtags).\n</li></ul>\n</li><li><strong><code>«atpMixed» TopicOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+topic1</code>, Kardinalität <code>0..1</code>).\n</li><li>Vermittlungsknoten zur Kapselung von Unterthemen oder dynamischen MSR-Modellabfragen (<em>MsrQuery</em>).\n</li><li>Komponiert <code>Topic1</code> (<code>+topic1</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong><code>Topic1</code>:</strong>\n<ul class=\"fig-list\"><li>Repräsentiert eine thematische Untereinheit (<code>Identifiable</code>, <code>Paginateable</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapter</code>, Kardinalität <code>0..1</code>).\n</li><li>Ermöglicht die rekursive Schachtelung von Unterkapiteln oder die Einbindung über dynamische Modellabfragen.\n</li><li>Komponiert rekursiv <code>Chapter</code> (<code>+chapter</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong>Stereotypen und Tagged Values:</strong>\n<ul class=\"fig-list\"><li><strong><code>«atpVariation»</code></strong> (auf den Kompositionen zu <code>Topic1</code> und <code>Chapter</code>): Markiert Variation Points für das AUTOSAR-Variantenmanagement.\n</li><li><strong>Tagged Value <code>vh.latestBindingTime = postBuild</code>:</strong> Festlegung, dass Dokumentationsvarianten bis zum Post-Build-Zeitpunkt über Systemkonstanten/Variantenkriterien gebunden bzw. selektiert werden können.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeitverhalten im Sinne von Mikrocontroller-Ausführung, BSW-Zustandswechseln, RTOS-Tasks oder API-Callbacks.\n</li><li><strong>Tool- und Build-Pipeline-Ablauf:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen des Modells:</strong> Der ARXML-Parser liest die Dokumentationshierarchie von Kapiteln und Unterthemen in einen kohärenten AST ein.\n</li><li><strong>Query-Evaluation:</strong> <code>TopicOrMsrQuery</code> und <code>ChapterOrMsrQuery</code> werden zur Tool-Laufzeit ausgewertet; dynamische Abfragen werden aufgelöst und durch konkrete Modellelemente substituiert.\n</li><li><strong>Variabilitätsauflösung (<code>«atpVariation»</code>):</strong> Evaluierung von Bindungsformeln und Selektion der gültigen Dokumentationszweige anhand der definierten Post-Build-Bindungszeit.\n</li><li><strong>Dokumentengenerierung / Rendering:</strong> Serialisierung des aufgelösten <code>ChapterModel</code> in Zielformate (z. B. PDF, HTML) unter Berücksichtigung der <code>Paginateable</code>-Attribute.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rolle im AUTOSAR-Standard:</strong> Definiert das formale Metamodell für strukturierte Dokumentation innerhalb des Generic Structure Template (<code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>).\n</li><li><strong>Regeln für Modellierung und ARXML-Validierung:</strong>\n<ul class=\"fig-list\"><li><strong>Eindeutigkeit:</strong> Durch Vererbung von <code>Identifiable</code> müssen Instanzen von <code>Chapter</code> und <code>Topic1</code> gültige <code>SHORT-NAME</code>-Elemente besitzen, die innerhalb ihres Gültigkeitsbereichs eindeutig sind.\n</li><li><strong>XML-Serialisierung (<code>«atpMixed»</code>):</strong> <code>ChapterContent</code>, <code>TopicOrMsrQuery</code> und <code>ChapterOrMsrQuery</code> erlauben gemischten Inhalt; Validierungswerkzeuge müssen mixed-content-fähige XML-Parser einsetzen.\n</li><li><strong>Splitting-Restriktion:</strong> Da die Kompositionen zu <code>Topic1</code> und <code>Chapter</code> keinen <code>«atpSplitable»</code>-Stereotyp tragen, ist ein Aufteilen dieser spezifischen Aggregationen über separate ARXML-Dateigrenzen hinweg metamodellseitig nicht gestattet.\n</li><li><strong>Variantenauflösung:</strong> Variation Points mit <code>vh.latestBindingTime = postBuild</code> verlangen, dass nachgelagerte Tools ungebundene Varianten bis zur Konfigurationsphase vorhalten können.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f8d0f699af3e736e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Strukturdiagramm (AUTOSAR Template Specification).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der hierarchischen Dokumentationsstruktur im AUTOSAR-Metamodell (<em>Generic Structure Template</em> – <code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>, Kapitel 9: Documentation).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die formale ARXML-Repräsentation von Dokumentationsinhalten (<code>Chapter</code>, <code>Topic1</code>, Fließtextinhalte). Dies ermöglicht das strukturierte Einbetten, Splitten und Variieren technischer Spezifikationen, Architekturdokumente und generierter Berichte direkt innerhalb des AUTOSAR-Datenmodells.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Chapter</code>:</strong> \n<ul class=\"fig-list\"><li>Repräsentiert ein eigenständiges Dokumentenkapitel.\n</li><li>Realisiert die Metamodell-Traits <code>Identifiable</code> (Besitz eines <code>shortName</code>, Namespace- und Adressierungsfähigkeit) sowie <code>Paginateable</code> (Paginierungssteuerung, z. B. erzwungene Seitenumbrüche).\n</li></ul>\n</li><li><strong><code>ChapterModel</code>:</strong>\n<ul class=\"fig-list\"><li>Zentraler Inhaltscontainer eines Kapitels.\n</li><li>Steht in einer strikten 1:1-Kompositionsbeziehung zu <code>Chapter</code> (<code>+chapterModel 1</code> als Ziel, Kompositionsraute bei <code>Chapter</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterContent</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapterContent</code>, Kardinalität <code>0..1</code>).\n</li><li>Nimmt primäre Dokumentationsstrukturen auf (z. B. Absätze, Listen, Tabellen, Abbildungen). Der Stereotyp <code>«atpMixed»</code> gestattet XML-Mixed-Content (Kombination aus Rohtext und XML-Elementtags).\n</li></ul>\n</li><li><strong><code>«atpMixed» TopicOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+topic1</code>, Kardinalität <code>0..1</code>).\n</li><li>Vermittlungsknoten zur Kapselung von Unterthemen oder dynamischen MSR-Modellabfragen (<em>MsrQuery</em>).\n</li><li>Komponiert <code>Topic1</code> (<code>+topic1</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong><code>Topic1</code>:</strong>\n<ul class=\"fig-list\"><li>Repräsentiert eine thematische Untereinheit (<code>Identifiable</code>, <code>Paginateable</code>).\n</li></ul>\n</li><li><strong><code>«atpMixed» ChapterOrMsrQuery</code>:</strong>\n<ul class=\"fig-list\"><li>Aggregiert in <code>ChapterModel</code> (<code>+chapter</code>, Kardinalität <code>0..1</code>).\n</li><li>Ermöglicht die rekursive Schachtelung von Unterkapiteln oder die Einbindung über dynamische Modellabfragen.\n</li><li>Komponiert rekursiv <code>Chapter</code> (<code>+chapter</code>, Kardinalität <code>1</code>).\n</li></ul>\n</li><li><strong>Stereotypen und Tagged Values:</strong>\n<ul class=\"fig-list\"><li><strong><code>«atpVariation»</code></strong> (auf den Kompositionen zu <code>Topic1</code> und <code>Chapter</code>): Markiert Variation Points für das AUTOSAR-Variantenmanagement.\n</li><li><strong>Tagged Value <code>vh.latestBindingTime = postBuild</code>:</strong> Festlegung, dass Dokumentationsvarianten bis zum Post-Build-Zeitpunkt über Systemkonstanten/Variantenkriterien gebunden bzw. selektiert werden können.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeitverhalten im Sinne von Mikrocontroller-Ausführung, BSW-Zustandswechseln, RTOS-Tasks oder API-Callbacks.\n</li><li><strong>Tool- und Build-Pipeline-Ablauf:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen des Modells:</strong> Der ARXML-Parser liest die Dokumentationshierarchie von Kapiteln und Unterthemen in einen kohärenten AST ein.\n</li><li><strong>Query-Evaluation:</strong> <code>TopicOrMsrQuery</code> und <code>ChapterOrMsrQuery</code> werden zur Tool-Laufzeit ausgewertet; dynamische Abfragen werden aufgelöst und durch konkrete Modellelemente substituiert.\n</li><li><strong>Variabilitätsauflösung (<code>«atpVariation»</code>):</strong> Evaluierung von Bindungsformeln und Selektion der gültigen Dokumentationszweige anhand der definierten Post-Build-Bindungszeit.\n</li><li><strong>Dokumentengenerierung / Rendering:</strong> Serialisierung des aufgelösten <code>ChapterModel</code> in Zielformate (z. B. PDF, HTML) unter Berücksichtigung der <code>Paginateable</code>-Attribute.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rolle im AUTOSAR-Standard:</strong> Definiert das formale Metamodell für strukturierte Dokumentation innerhalb des Generic Structure Template (<code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>).\n</li><li><strong>Regeln für Modellierung und ARXML-Validierung:</strong>\n<ul class=\"fig-list\"><li><strong>Eindeutigkeit:</strong> Durch Vererbung von <code>Identifiable</code> müssen Instanzen von <code>Chapter</code> und <code>Topic1</code> gültige <code>SHORT-NAME</code>-Elemente besitzen, die innerhalb ihres Gültigkeitsbereichs eindeutig sind.\n</li><li><strong>XML-Serialisierung (<code>«atpMixed»</code>):</strong> <code>ChapterContent</code>, <code>TopicOrMsrQuery</code> und <code>ChapterOrMsrQuery</code> erlauben gemischten Inhalt; Validierungswerkzeuge müssen mixed-content-fähige XML-Parser einsetzen.\n</li><li><strong>Splitting-Restriktion:</strong> Da die Kompositionen zu <code>Topic1</code> und <code>Chapter</code> keinen <code>«atpSplitable»</code>-Stereotyp tragen, ist ein Aufteilen dieser spezifischen Aggregationen über separate ARXML-Dateigrenzen hinweg metamodellseitig nicht gestattet.\n</li><li><strong>Variantenauflösung:</strong> Variation Points mit <code>vh.latestBindingTime = postBuild</code> verlangen, dass nachgelagerte Tools ungebundene Varianten bis zur Konfigurationsphase vorhalten können.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-0891077d2a366bc1", "to": "FIG-881bffb71b63a4fd", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Komposition <code>ChapterOrMsrQuery</code> zu <code>Chapter</code> (<code>+chapter</code>): Stereotyp von <code>«atpVariation,atpSplitable»</code> (im Vorgänger abgeschnitten als <code>«atpVariation,atpSplitab</code>) geändert zu <code>«atpVariation»</code>.\n</li><li>Komposition <code>TopicOrMsrQuery</code> zu <code>Topic1</code> (<code>+topic1</code>): Stereotyp von <code>«atpVariation,atpSplitable»</code> geändert zu <code>«atpVariation»</code>.\n</li></ul>"}, {"from": "FIG-881bffb71b63a4fd", "to": "FIG-f8d0f699af3e736e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
